import aiohttp
from typing import Optional
import os
from tenacity import retry, stop_after_attempt, wait_exponential

class HiddifyClient:
    def __init__(self):
        self.base_url = f"{os.getenv('PANEL_HIDDIFY_URL')}/api/v2/"
        self.headers = {"Hiddify-API-Key": os.getenv("PANEL_HIDDIFY_API_KEY")}

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    async def create_user(self, username: str, expiry_days: int, traffic_limit: Optional[int] = None) -> dict:
        import time
        payload = {
            "username": username,
            "expiry_time": int(time.time()) + (expiry_days * 24 * 60 * 60),
            "data_limit": traffic_limit,
            "enabled": True
        }

        async with aiohttp.ClientSession(headers=self.headers) as session:
            async with session.post(f"{self.base_url}admin/user/", json=payload) as resp:
                resp.raise_for_status()
                return await resp.json()

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    async def get_user(self, uuid: str) -> dict:
        async with aiohttp.ClientSession(headers=self.headers) as session:
            async with session.get(f"{self.base_url}admin/user/{uuid}") as resp:
                resp.raise_for_status()
                return await resp.json()

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    async def update_user(self, uuid: str, expiry_days: int, traffic_limit: Optional[int] = None) -> dict:
        import time
        payload = {
            "expiry_time": int(time.time()) + (expiry_days * 24 * 60 * 60),
            "data_limit": traffic_limit
        }

        async with aiohttp.ClientSession(headers=self.headers) as session:
            async with session.put(f"{self.base_url}admin/user/{uuid}", json=payload) as resp:
                resp.raise_for_status()
                return await resp.json()

    @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
    async def delete_user(self, uuid: str) -> bool:
        async with aiohttp.ClientSession(headers=self.headers) as session:
            async with session.delete(f"{self.base_url}admin/user/{uuid}") as resp:
                resp.raise_for_status()
                return resp.status == 200

